import sys

def main():
    data = sys.stdin.buffer.read().split(b'\n')
    sums = {}
    get = sums.get
    for line in data[1:]:
        if not line:
            continue
        parts = line.rstrip(b'\r').split(b',')
        if len(parts) < 3:
            continue
        cat = parts[1]
        sums[cat] = get(cat, 0.0) + float(parts[2])
    out = []
    for cat in sorted(sums):
        out.append(cat.decode() + ',' + '%.2f' % sums[cat])
    if out:
        sys.stdout.write('\n'.join(out) + '\n')

main()

import sys

def main():
    toks = sys.stdin.buffer.read().split()
    sums = {}
    get = sums.get
    it = iter(toks[3:])
    for _, c, v in zip(it, it, it):
        sums[c] = get(c, 0.0) + float(v)
    out = [c.decode() + ',' + '%.2f' % sums[c] for c in sorted(sums)]
    if out:
        sys.stdout.write('\n'.join(out) + '\n')

main()

import sys

def main():
    sums = {}
    get = sums.get
    for line in sys.stdin.buffer.read().split(b'\n')[1:]:
        try:
            _, c, v = line.split(b',')[:3]
        except ValueError:
            continue
        sums[c] = get(c, 0.0) + float(v)
    out = [c.decode() + ',' + '%.2f' % sums[c] for c in sorted(sums)]
    if out:
        sys.stdout.write('\n'.join(out) + '\n')

main()
